# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256
#define WARP_SIZE 32

__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void fused_batchnorm3d_meansub_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C, int spatial_size,
    float eps
) {
    int nc = blockIdx.x;
    int n = nc / C;
    int c = nc % C;

    const float* in_ptr = input + (long long)nc * spatial_size;
    float* out_ptr = output + (long long)nc * spatial_size;

    float rm = running_mean[c];
    float rv = running_var[c];
    float w = weight[c];
    float b = bias[c];
    float inv_std = rsqrtf(rv + eps);

    __shared__ float shared_sum[BLOCK_SIZE / WARP_SIZE];

    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < spatial_size; i += BLOCK_SIZE) {
        float val = in_ptr[i];
        float normalized = (val - rm) * inv_std * w + b;
        out_ptr[i] = normalized;
        local_sum += normalized;
    }

    float warp_sum = warpReduceSum(local_sum);
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    if (lane == 0) {
        shared_sum[wid] = warp_sum;
    }
    __syncthreads();

    float block_sum = 0.0f;
    if (threadIdx.x < BLOCK_SIZE / WARP_SIZE) {
        block_sum = shared_sum[threadIdx.x];
    }
    block_sum = warpReduceSum(block_sum);

    __shared__ float spatial_mean;
    if (threadIdx.x == 0) {
        spatial_mean = block_sum / (float)spatial_size;
    }
    __syncthreads();

    for (int i = threadIdx.x; i < spatial_size; i += BLOCK_SIZE) {
        out_ptr[i] -= spatial_mean;
    }
}

torch::Tensor fused_batchnorm3d_meansub_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps,
    bool training
