    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    int spatial_size = D * H * W;

    auto output = torch::empty_like(x);

    int num_blocks = N * C;

    fused_batchnorm3d_meansub_kernel<<<num_blocks, BLOCK_SIZE>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        N, C, spatial_size,
        (float)eps
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

